// Regenerates src/index.ts from the files ts-rs wrote to src/generated (T0.2.7).
import { readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = new URL("..", import.meta.url).pathname;
const generated = join(root, "src", "generated");

const modules = readdirSync(generated)
  .filter((file) => file.endsWith(".ts"))
  .map((file) => file.slice(0, -".ts".length))
  .sort();

const lines = [
  "// Generated by scripts/build-index.mjs from ts-rs output. Do not edit this file manually.",
  "",
  ...modules.map((name) => `export type * from "./generated/${name}";`),
  "",
];

writeFileSync(join(root, "src", "index.ts"), lines.join("\n"));
console.log(`api-types: indexed ${modules.length} types`);
